function H = cyclic_subgroup(a, p)
% CYCLIC_SUBGROUP The cyclic subgroup of Z_p* that is generated by a.
%   H = cyclic_subgroup(a, p) gives the row [a^0, a^1, a^2, ..., a^(k-1)] (all mod p), where k is the order of a.
%   So H starts with 1, has k numbers, and they are all different. a^k would be 1 again.
%   a is a whole number from 1 to p-1. p must be a prime number from 2 to 5000.
if ~is_whole_number(p) || p < 2 || p > 5000 || ~is_prime_number(p)
    error('cyclic_subgroup:prime', 'p must be a prime number from 2 to 5000.');
end
if ~is_whole_number(a) || a < 1 || a > p - 1
    error('cyclic_subgroup:range', 'a must be one whole number from 1 to p-1.');
end
p = double(p);
a = double(a);
k = element_order(a, p);
H = zeros(1, k);
v = 1;
for i = 1:k
    H(i) = v;
    v = mod(v * a, p);
end
end
